// sorted array: O(n) time, O(1) memory
int lo = 0, hi = nums.Length - 1;
while (lo < hi) {
    int sum = nums[lo] + nums[hi];
    if (sum == target) return new[] { lo, hi };
    if (sum < target) lo++;   // nums[lo] is too small even with the largest one
    else hi--;                // nums[hi] is too large even with the smallest one
}
